 59	/// K4's limbs per stored entry at each precision (`K4R/adaptive.rs:2455-2459`).
 60	pub const LIMBS_PER_ENTRY: [(u32, usize); 4] = [(128, 4), (256, 4), (512, 8), (1024, 16)];
