 71	/// The FNV-1a digest of a byte string (K6's fixed digest; not cryptographic).
 72	pub fn fnv64(bytes: &[u8]) -> u64 {
 73	    let mut h = Fnv64::new();
 74	    h.update(bytes);
 75	    h.finish()
 76	}
