 97	/// K4's profile rule on the structural free–free adjacency: (profile entries,
 98	/// half-bandwidth, blocks).
 99	pub fn structural_profile(
100	    dofs: usize,
101	    free: &[usize],
102	    adjacent: &[Vec<usize>],
103	) -> (usize, usize, usize) {
104	    let mut position = vec![usize::MAX; dofs];
105	    for (a, &g) in free.iter().enumerate() {
106	        position[g] = a;
107	    }
108	    let adjacency: Vec<Vec<usize>> = free
109	        .iter()
110	        .map(|&g| {
111	            let node = g / DOF_PER_NODE;
112	            let mut out = Vec::new();
113	            for &other in std::iter::once(&node).chain(adjacent[node].iter()) {
114	                for c in 0..DOF_PER_NODE {
115	                    let h = other * DOF_PER_NODE + c;
116	                    if h != g && position[h] != usize::MAX {
117	                        out.push(position[h]);
118	                    }
119	                }
120	            }
121	            out
122	        })
123	        .collect();
124	    drop(position);
125	    let order = reverse_cuthill_mckee(&adjacency);
126	    let mut rank = vec![0usize; free.len()];
127	    for (k, &a) in order.iter().enumerate() {
128	        rank[a] = k;
129	    }
130	    let (mut profile, mut bandwidth) = (0usize, 0usize);
131	    for (i, &a) in order.iter().enumerate() {
132	        let first = adjacency[a]
133	            .iter()
134	            .map(|&b| rank[b])
135	            .chain(std::iter::once(i))
136	            .min()
137	            .unwrap_or(i);
138	        profile += i - first + 1;
139	        bandwidth = bandwidth.max(i - first);
140	    }
141	    // Blocks: connected components of the free–free adjacency.
142	    let mut block = vec![usize::MAX; free.len()];
143	    let mut blocks = 0;
144	    let mut stack = Vec::new();
145	    for seed in 0..free.len() {
146	        if block[seed] != usize::MAX {
147	            continue;
148	        }
149	        block[seed] = blocks;
150	        stack.push(seed);
151	        while let Some(a) = stack.pop() {
152	            for &b in &adjacency[a] {
153	                if block[b] == usize::MAX {
154	                    block[b] = blocks;
155	                    stack.push(b);
156	                }
157	            }
158	        }
159	        blocks += 1;
160	    }
161	    (profile, bandwidth, blocks)
162	}
