269	/// The rows of the fallback's per-state row list at its peak under the move
270	/// model (RV22-2). The list starts empty and takes one push per free row
271	/// (`K4R/adaptive.rs:1476`, `:1515`), so its capacity doubles from 1 (the
272	/// minimum for elements over 1 KiB) to C = the next power of two ≥ its
273	/// length ≤ n_f; its last growth holds the old C/2 rows and the new C.
274	pub const fn fallback_row_list_rows(free_dofs: u128) -> u128 {
275	    let c = next_pow2(free_dofs);
276	    c + c / 2
277	}
