279	/// The least power of two ≥ x (0 for 0).
280	pub const fn next_pow2(x: u128) -> u128 {
281	    if x == 0 {
282	        return 0;
283	    }
284	    let mut c = 1;
285	    while c < x {
286	        c *= 2;
287	    }
288	    c
289	}
