383	/// The W1 estimate and its terms (bytes).
384	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
385	pub struct W1Estimate {
386	    /// The stop rule's tracker bound (a transient at each decision).
387	    pub decide: u128,
388	    /// Each attempt's solve transient, with the fallback.
389	    pub solve: [u128; 4],
390	    /// Each verification pass's transient, at its larger of the shift and
391	    /// after it.
392	    pub pass: [u128; 3],
393	    /// Alive through the call: the harness's model and frames, the source
394	    /// twice, the case and the group.
395	    pub fixed: u128,
396	    /// S(p): each attempt's shared build (kept in the group cache).
397	    pub shared: [u128; 4],
398	    /// U(p): each attempt's state.
399	    pub state: [u128; 4],
400	    /// V(P): each verification's shared data (kept).
401	    pub verify: [u128; 3],
402	    /// E_max: the peak over the whole schedule (128 … v1024).
403	    pub max: u128,
404	    /// E_sel128: the peak of the path selected at 128 (128, 256, v256).
405	    pub sel128: u128,
406	}
