408	/// The W1 estimate (plan §3.5; ROOT's ruling on RV22-2). Each phase's
409	/// transient is added to the bytes kept when it runs, so the estimate bounds
410	/// every modelled phase rather than tracking the peak.
411	pub fn estimate(c: &W1Counts, s: &W1SizeFacts) -> W1Estimate {
412	    let u = |x: usize| x as u128;
413	    let (m, n, nf, nnz) = (
414	        u(c.members),
415	        u(c.dofs),
416	        u(c.free_dofs),
417	        u(c.pattern_entries),
418	    );
419	    let (p_entries, blocks, rows) = (u(c.profile_entries), u(c.blocks.max(1)), u(c.rows));
420	    let (nodes, r, loads, stations) = (u(c.nodes), u(c.constraints), u(c.loads), u(c.stations));
421	    let enc = u(c.source_encoding_len);
422	    let w = wide_bytes;
423	
424	    let harness =
425	        nodes * MODEL_NODE_BYTES + m * MODEL_MEMBER_BYTES + loads * 16 + m * u(s.frame_element);
426	    let source = 24 * nodes
427	        + m * u(s.straight_member)
428	        + r * u(s.constraint)
429	        + loads * (u(s.nodal_load) + SOURCE_ID_BYTES)
430	        + stations * u(s.station)
431	        + 16 * n
432	        + 4 * nodes;
433	    let case = loads * LEDGER_ENTRY_BYTES
434	        + r * PRESCRIBED_ENTRY_BYTES
435	        + enc
436	        + rows * u(s.quantity_meta)
437	        + 8 * u(c.bodies);
438	    let group = 8 * (n + 1)
439	        + 16 * nnz
440	        + 8 * (nnz + 1)
441	        + m * CONTRIBUTIONS_PER_MEMBER * CONTRIBUTION_BYTES
442	        + 32 * nf
443	        + 8 * n
444	        + 12 * nf
445	        + 24 * blocks;
446	    let group_build = m * CONTRIBUTIONS_PER_MEMBER * (TAGGED_CONTRIBUTION_BYTES + 16);
447	    let fixed = harness + 2 * source + case + group;
448	
449	    let shared = ATTEMPT_WIDTHS.map(|(_, l, r)| {
450	        m * (MEMBER_OPERATOR_WIDES * w(l) + MEMBER_OPERATOR_EXTRA)
451	            + nnz * (w(l) + w(r))
452	            + m * (BOUNDED_WIDES * w(r) + BOUNDED_EXTRA)
453	            + p_entries * w(l)
454	            + nf * (FACTOR_ROW_WIDES * w(l) + FACTOR_ROW_EXTRA)
455	            + blocks * w(l)
456	    });
457	    let shared_build = ATTEMPT_WIDTHS.map(|(p, _, r)| {
458	        if p == 1024 {
459	            0
460	        } else {
461	            m * (MEMBER_OPERATOR_WIDES * w(r) + MEMBER_OPERATOR_EXTRA)
462	        }
463	    });
464	    let state = ATTEMPT_WIDTHS.map(|(_, l, _)| (n + 6 * m + rows) * w(l));
465	    // KF1: a solve attempt's trackers (bounded) and their tables.
466	    let solve_trackers = SOLVE_TRACKER_PEAK_ROWS * TRACKER_ENTRY_BYTES
467	        + (VEC_SLACK * SOLVE_TABLE_ROWS_PER_FREE_DOF + TABLE_MOVE_EXTRA)
468	            * nf
469	            * TRACKER_TABLE_ENTRY_BYTES;
470	    // The solve (`K4R/adaptive.rs:1554-1700`): its working vectors and the
471	    // residual gate's row list, then the fallback (`:1437-1500`, RV22-2):
472	    // `u_free`, the evaluated states and `abar_q`, alive throughout; then
473	    // either `assemble_bounded`'s member blocks (while `abar_q` is built) or,
474	    // per state, the copy of u and the row list under the move model.
475	    let solve = ATTEMPT_WIDTHS.map(|(_, l, r)| {
476	        let fallback = nf * w(l)
477	            + EVALUATED_STATES * (nf * w(l) + VEC_HEADER_BYTES)
