484	        nnz * w(l)
485	            + m * BLOCK_WIDES * w(ww)
486	            + blocks * (BLOCK_BOUND_WIDES * w(l) + BLOCK_BOUND_EXTRA)
487	    });
488	    let verify_build = VERIFY_WIDTHS.map(|(p, l, ww)| {
489	        m * (BOUNDED_WIDES * w(l) + BOUNDED_EXTRA)
490	            + m * BLOCK_WIDES * w(l)
491	            + if p == 1024 {
492	                0
493	            } else {
494	                m * (MEMBER_OPERATOR_WIDES * w(ww) + MEMBER_OPERATOR_EXTRA)
495	            }
496	    });
497	    // The report, kept after the pass: its row vectors and two over the free
498	    // DOFs.
499	    let report = VERIFY_WIDTHS
500	        .map(|(_, l, _)| REPORT_ROW_VECTORS * rows * (w(l) + OPTION_EXTRA) + 2 * nf * w(l));
501	    // The pass (`K4R/verify.rs:731-925`, RV22-2): its locals, with either the
