545	            }
546	        }
547	    }
548	    let max = peak.max(kept + report[2] + end);
549	    W1Estimate {
550	        decide,
551	        solve,
552	        pass,
553	        fixed,
554	        shared,
555	        state,
556	        verify,
557	        max,
558	        sel128,
559	    }
560	}
