562	/// K4's storage bytes at precision `p` as K4 counts them: (pattern + profile)
563	/// entries × limbs × 8.
564	pub fn storage_bytes(c: &W1Counts, p: u32) -> u128 {
565	    (c.pattern_entries as u128 + c.profile_entries as u128) * limbs_per_entry(p) as u128 * 8
566	}

