 34	fn gate(g: &Option<GateTest>) -> Option<String> {
 35	    g.as_ref().map(|g| match g {
 36	        GateTest::Coalesced => "coalesced".to_string(),
 37	        GateTest::Bounded { state, evaluated } => format!("bounded:{state}/{evaluated}"),
 38	    })
 39	}
