 41	/// Whether the call ended on a budget (a stop: the limits are `u64::MAX`).
 42	pub fn budget_reached(solve: &W1Solve) -> bool {
 43	    solve.exhausted
 44	        || matches!(
 45	            solve.outcome,
 46	            CaseOutcome::Unresolved {
 47	                reason: UnresolvedReason::Budget(_),
 48	                ..
 49	            }
 50	        )
 51	}
