 53	/// The repeat's determinism digest: the publication's and the evidence's
 54	/// `Debug` digests (a selected case), or the outcome's (otherwise; it holds
 55	/// only the reason and the attempts), and the charged work, folded into one
 56	/// FNV-1a. The retained solve's caches are not formatted.
 57	pub fn repeat_digest(solve: &W1Solve) -> (u64, u64) {
 58	    let parts = match &solve.outcome {
 59	        CaseOutcome::Selected(s) => vec![debug_digest(s.publish()), debug_digest(s.evidence())],
 60	        other => vec![debug_digest(other)],
 61	    };
 62	    let mut h = Fnv64::new();
 63	    let mut len = 0;
 64	    for (l, f) in parts {
 65	        len += l;
 66	        h.update(&l.to_le_bytes());
 67	        h.update(&f.to_le_bytes());
 68	    }
 69	    h.update(&solve.charged.to_le_bytes());
 70	    (len, h.finish())
 71	}
 72	
 73	/// The outcome line of one repeat.
 74	pub fn outcome_line(repeat: usize, solve: &W1Solve) {
 75	    let attempts = attempts_of(&solve.outcome);
 76	    let mut line = Line::new("outcome")
 77	        .n("repeat", repeat)
 78	        .s("class", outcome_class(&solve.outcome));
 79	    line = match &solve.outcome {
 80	        CaseOutcome::Selected(s) => {
 81	            let publication = s.publish();
 82	            let evidence = s.evidence();
 83	            let counts = class_counts(publication);
 84	            let (pub_len, pub_fnv) = debug_digest(publication);
 85	            let (ev_len, ev_fnv) = debug_digest(evidence);
 86	            line.n("selected_precision", s.selected_precision())
 87	                .n("verification_precision", evidence.verification_precision)
 88	                .null("reason")
 89	                .n("rows", publication.rows.len())
 90	                .n("rows_relative_verified", counts[0])
 91	                .n("rows_absolute_verified", counts[1])
 92	                .n("rows_input_derived", counts[2])
 93	                .n("rows_unpublishable", counts[3])
 94	                .n("publication_debug_len", pub_len)
 95	                .hex("publication_fnv64", pub_fnv)
 96	                .n("evidence_debug_len", ev_len)
 97	                .hex("evidence_fnv64", ev_fnv)
 98	                .hex(
 99	                    "retained_state_fnv64",
100	                    fnv64(&evidence.retained_state_encoding),
101	                )
102	        }
103	        CaseOutcome::Refused { refusal, .. } => line
104	            .null("selected_precision")
105	            .null("verification_precision")
106	            .s("reason", &bounded(format!("{refusal:?}"))),
107	        CaseOutcome::Unresolved { reason, .. } => line
108	            .null("selected_precision")
109	            .null("verification_precision")
110	            .s("reason", &bounded(format!("{reason:?}"))),
111	    };
112	    line = line
113	        .n("attempts", attempts.len())
114	        .n("meter_charged", solve.charged)
115	        .b("budget_reached", budget_reached(solve));
116	    for w in work_by_precision(attempts) {
117	        line = line
118	            .n(&format!("work_{}_attempts", w.precision), w.attempts)
119	            .n(&format!("work_{}_own", w.precision), w.own_total)
120	            .n(&format!("work_{}_shared", w.precision), w.shared_total);
121	    }
122	    line.emit();
123	}
