125	/// One `attempt` line per attempt.
126	pub fn attempt_lines(repeat: usize, attempts: &[AttemptRecord]) {
127	    for (index, a) in attempts.iter().enumerate() {
128	        let mut line = Line::new("attempt")
129	            .n("repeat", repeat)
130	            .n("index", index)
131	            .n("precision", a.precision)
132	            .s("role", &format!("{:?}", a.role))
133	            .s("outcome", &bounded(format!("{:?}", a.outcome)))
134	            .n("residual_basis", a.residual_basis)
135	            .n("corrections", a.corrections)
136	            .opt_s("gate", gate(&a.gate).as_deref())
137	            .f("pivot_margin_min", a.pivot_margin_min)
138	            .f("rcond", a.rcond)
139	            .f("residual_worst", a.residual_worst)
140	            .n("storage_pattern_entries", a.storage.pattern_entries)
141	            .n("storage_profile_entries", a.storage.profile_entries)
142	            .n("storage_limbs_per_entry", a.storage.limbs_per_entry);
143	        for (name, value) in stage_fields(&a.stages) {
144	            line = line.n(&format!("own_{name}"), value);
145	        }
146	        for (name, value) in stage_fields(&a.shared_stages) {
147	            line = line.n(&format!("shared_{name}"), value);
148	        }
149	        let v = a.verification.as_ref();
150	        let (own_unstaged, shared_unstaged) = unstaged(a);
151	        line.b("stages_complete", stages_complete(a))
152	            .n("own_unstaged", own_unstaged)
153	            .n("shared_unstaged", shared_unstaged)
154	            .n("own_total", own_total(a))
155	            .n("charged_by", charged_by(a))
156	            .n("shared_work", a.shared_work)
157	            .b("shared_built_here", a.shared_built_here)
158	            .n("stop_rule_work", a.stop_rule_work)
159	            .n("verification_work", a.verification_work)
160	            .n("verification_shared_work", a.verification_shared_work)
161	            .b(
162	                "verification_shared_built_here",
163	                a.verification_shared_built_here,
164	            )
165	            .opt_n("verification_data_blocks", v.map(|v| v.data_blocks))
166	            .opt_n(
167	                "verification_shift_factorizations",
168	                v.map(|v| v.shift_factorizations),
169	            )
170	            .opt_n("verification_uc_missing", v.and_then(|v| v.uc_missing))
171	            .opt_n("verification_g_max", v.map(|v| v.g_max))
172	            .opt_n("verification_g_violation", v.and_then(|v| v.g_violation))
173	            .emit();
174	    }
175	}
