184	/// The W1 parity items (plan §3.4). A false item is a stop for the runner.
185	pub fn parity_lines(repeat: usize, counts: &W1Counts, solve: &W1Solve) {
186	    let attempts = attempts_of(&solve.outcome);
187	    if !attempts.is_empty() {
188	        parity(
189	            "w1_profile_equals_storage",
190	            repeat,
191	            attempts
192	                .iter()
193	                .all(|a| a.storage.profile_entries == counts.profile_entries),
194	        )
195	        .n("counts_profile_entries", counts.profile_entries)
196	        .emit();
197	        parity(
198	            "w1_pattern_equals_storage",
199	            repeat,
200	            attempts
201	                .iter()
202	                .all(|a| a.storage.pattern_entries == counts.pattern_entries),
203	        )
204	        .n("counts_pattern_entries", counts.pattern_entries)
205	        .emit();
206	        parity(
207	            "w1_limbs_equal_table",
208	            repeat,
209	            attempts
210	                .iter()
211	                .all(|a| a.storage.limbs_per_entry == limbs_per_entry(a.precision)),
212	        )
213	        .emit();
214	        parity(
215	            "w1_stages_equal_totals",
216	            repeat,
217	            stages_equal_totals(attempts),
218	        )
219	        .emit();
220	        parity(
221	            "w1_work_closes",
222	            repeat,
223	            work_closes(attempts, solve.charged),
224	        )
225	        .n("meter_charged", solve.charged)
226	        .emit();
227	    }
228	    if let CaseOutcome::Selected(s) = &solve.outcome {
229	        let fnv = fnv64(&s.evidence().source_encoding);
230	        parity(
231	            "w1_source_encoding_equals_evidence",
232	            repeat,
233	            fnv == counts.source_encoding_fnv64,
234	        )
235	        .hex("evidence_source_fnv64", fnv)
236	        .emit();
237	    }
238	    parity("w1_budget_not_reached", repeat, !budget_reached(solve)).emit();
239	}
