257	/// The line of one prefix call (`prefix`, a new kind): its limit and segment,
258	/// its outcome, and whether its completed segments equal the full call's.
259	pub fn prefix_line(j: usize, label: &str, limit: u64, full: &[AttemptRecord], solve: &W1Solve) {
260	    let reason = match &solve.outcome {
