 471	/// c′ = |L|D|Lᵀ|e, every operation upward (emu7's `nl_pass`); refusals as in
 472	/// `u_pass` (amendment A2).
 473	pub(crate) fn nl_pass<const L: usize, F: ProfileLdl<L>>(
 474	    ctx: &mut WideContext<L>,
 475	    sum: &mut ExactWideSum,
 476	    guard: &StageGuard,
 477	    f: &F,
 478	    block_of_row: &[u32],
 479	    refused: &mut [Option<BoundRefusal>],
 480	) -> Result<Vec<Wide<L>>, AttemptStop>
 481	where
 482	    Wide<L>: SupportedWidth,
 483	{
 484	    let n = f.rows();
 485	    let mut at = vec![Wide::<L>::ONE; n];
 486	    for i in 0..n {
 487	        let b = block_of_row[i] as usize;
 488	        if refused[b].is_some() {
 489	            continue;
 490	        }
 491	        for j in f.first_of(i)..i {
 492	            let l = f.entry(i, j).abs();
 493	            if l.is_zero() {
 494	                continue;
 495	            }
 496	            let Some(v) = refusable(
 497	                add_toward(ctx, sum, &at[j], &l, Toward::Up),
 498	                sum,
 499	                &mut refused[b],
 500	                BoundPass::NlColumn,
 501	                j,
 502	            )?
 503	            else {
 504	                break;
 505	            };
 506	            at[j] = v;
 507	        }
 508	    }
 509	    let mut bt = Vec::with_capacity(n);
 510	    for (i, a) in at.iter().enumerate() {
 511	        let b = block_of_row[i] as usize;
 512	        let v = if refused[b].is_none() {
 513	            refusable(
 514	                mul_toward(ctx, sum, &f.entry(i, i), a, Toward::Up),
 515	                sum,
 516	                &mut refused[b],
 517	                BoundPass::NlScale,
 518	                i,
 519	            )?
 520	        } else {
 521	            None
 522	        };
 523	        bt.push(v.unwrap_or(Wide::<L>::ZERO));
 524	    }
 525	    let mut ct = bt.clone();
 526	    for i in 0..n {
 527	        let b = block_of_row[i] as usize;
 528	        if refused[b].is_none() {
 529	            for j in f.first_of(i)..i {
 530	                let l = f.entry(i, j).abs();
 531	                if l.is_zero() {
 532	                    continue;
 533	                }
 534	                let Some(t) = refusable(
 535	                    mul_toward(ctx, sum, &l, &bt[j], Toward::Up),
 536	                    sum,
 537	                    &mut refused[b],
 538	                    BoundPass::NlRow,
 539	                    i,
 540	                )?
 541	                else {
 542	                    break;
 543	                };
 544	                let Some(v) = refusable(
 545	                    add_toward(ctx, sum, &ct[i], &t, Toward::Up),
 546	                    sum,
 547	                    &mut refused[b],
 548	                    BoundPass::NlRow,
 549	                    i,
 550	                )?
 551	                else {
 552	                    break;
 553	                };
 554	                ct[i] = v;
 555	            }
 556	        }
 557	        guard.check(ctx, sum)?;
 558	    }
 559	    Ok(ct)
 560	}
