 562	/// γ_m = m/(2^P − m), m = 2n + 2 (n all free DOFs), rounded upward.
 563	pub(crate) fn gamma_m<const L: usize>(
 564	    ctx: &mut WideContext<L>,
 565	    sum: &mut ExactWideSum,
 566	    free_count: usize,
 567	) -> Result<Wide<L>, AttemptStop>
 568	where
 569	    Wide<L>: SupportedWidth,
 570	{
 571	    let m = Wide::<L>::from_f64((2 * free_count + 2) as f64)?;
 572	    sum.clear();
 573	    sum.add_wide_scaled(&Wide::<L>::ONE, false, 1, i64::from(ctx.precision()))?;
 574	    sum.add_wide(&m, true)?;
 575	    // 2^P − m has at most P bits: the rounding is exact.
 576	    let den = sum.round(ctx)?;
 577	    div_toward(ctx, sum, &m, &den, Toward::Up)
 578	}
