 612	/// Per block: max over the rows `rows_of_block` of `values` (elimination order).
 613	fn block_max<const L: usize>(
 614	    values: &[Wide<L>],
 615	    block_of_row: &[u32],
 616	    blocks: usize,
 617	) -> Vec<Wide<L>>
 618	where
 619	    Wide<L>: SupportedWidth,
 620	{
 621	    let mut out = vec![Wide::<L>::ZERO; blocks];
 622	    for (i, v) in values.iter().enumerate() {
 623	        let b = block_of_row[i] as usize;
 624	        if v.cmp_value(&out[b]) == CmpOrdering::Greater {
 625	            out[b] = *v;
 626	        }
 627	    }
 628	    out
 629	}
