 636	/// U_c, N_L,c, t_c and Uc_c from per-row c and c′.
 637	fn bounds_from<const L: usize>(
 638	    ctx: &mut WideContext<L>,
 639	    sum: &mut ExactWideSum,
 640	    gamma: &Wide<L>,
 641	    u: &Wide<L>,
 642	    n_l: &Wide<L>,
 643	) -> Result<BlockBound<L>, AttemptStop>
 644	where
 645	    Wide<L>: SupportedWidth,
 646	{
 647	    let one = Wide::<L>::ONE;
 648	    let ug = mul_toward(ctx, sum, u, gamma, Toward::Up)?;
 649	    let t = mul_toward(ctx, sum, &ug, n_l, Toward::Up)?;
 650	    let uc = if t.cmp_value(&one) == CmpOrdering::Less {
 651	        let den = sub_toward(ctx, sum, &one, &t, Toward::Down)?;
 652	        Some(div_toward(ctx, sum, u, &den, Toward::Up)?)
 653	    } else {
 654	        None
 655	    };
 656	    Ok(BlockBound {
 657	        u: *u,
 658	        n_l: *n_l,
 659	        t,
 660	        uc,
 661	        refused: None,
 662	    })
 663	}
