 665	/// 7b per block, from a factor whose rows' blocks are `block_of_row`.
 666	/// `refused` holds one slot per block (all `None` on entry). The caller owns
 667	/// it, so a refusal recorded before a later stop in the same build survives
 668	/// that stop and reaches the evidence (RV23-1).
 669	pub(crate) fn uc_bounds<const L: usize, F: ProfileLdl<L>>(
 670	    ctx: &mut WideContext<L>,
 671	    sum: &mut ExactWideSum,
 672	    guard: &StageGuard,
 673	    f: &F,
 674	    block_of_row: &[u32],
 675	    refused: &mut [Option<BoundRefusal>],
 676	    gamma: &Wide<L>,
 677	) -> Result<Vec<BlockBound<L>>, AttemptStop>
 678	where
 679	    Wide<L>: SupportedWidth,
 680	{
 681	    // Amendment A2: a refusal makes only its own block's Uc_c unavailable.
 682	    let blocks = refused.len();
 683	    let c = u_pass(ctx, sum, guard, f, block_of_row, refused)?;
 684	    let ct = nl_pass(ctx, sum, guard, f, block_of_row, refused)?;
 685	    let u = block_max(&c, block_of_row, blocks);
 686	    let n_l = block_max(&ct, block_of_row, blocks);
 687	    let mut out = Vec::with_capacity(blocks);
 688	    for (b, slot) in refused.iter_mut().enumerate() {
 689	        if let Some(r) = slot {
 690	            out.push(BlockBound::refused(*r));
 691	            continue;
 692	        }
 693	        match refusable(
 694	            bounds_from(ctx, sum, gamma, &u[b], &n_l[b]),
 695	            sum,
 696	            slot,
 697	            BoundPass::Form,
 698	            usize::MAX,
 699	        )? {
 700	            Some(bound) => out.push(bound),
 701	            None => out.push(BlockBound::refused(slot.expect("recorded"))),
 702	        }
 703	    }
 704	    Ok(out)
 705	}
