 823	/// `factor()`'s loop, operation for operation, on K̃ with d̃_i = fl(K̃_ii − σ_c)
 824	/// in every block with a σ_c, and the pivot test d′_i > 0 (module
 825	/// documentation). With no block shifted it forms `factor()`'s L and D bit for
 826	/// bit wherever `factor()`'s pivot screen passes (the loop-parity test).
 827	///
 828	/// `refused` holds one slot per block (all `None` on entry): each block's
 829	/// first refusal of this factorization (A2; only an exponent refusal can occur
 830	/// in the context's operations). A refused block's later rows are not formed.
 831	/// The caller owns the slots, so a refusal survives a later stop (RV23-1).
 832	pub(crate) fn shifted_factor<const L: usize>(
 833	    ctx: &mut WideContext<L>,
 834	    sum: &ExactWideSum,
 835	    guard: &StageGuard,
 836	    profile: &ScaledProfile<L>,
 837	    sigma: &[Option<Wide<L>>],
 838	    refused: &mut [Option<BoundRefusal>],
 839	) -> Result<ShiftedFactor<L>, AttemptStop>
 840	where
 841	    Wide<L>: SupportedWidth,
 842	{
 843	    let n = profile.first.len();
 844	    let first = profile.first.clone();
 845	    let mut rows = profile.rows.clone();
 846	    let mut shifted = vec![None; n];
 847	    for i in 0..n {
 848	        let b = profile.block_of_row[i] as usize;
 849	        if let Some(s) = &sigma[b] {
 850	            if refused[b].is_some() {
 851	                continue;
 852	            }
 853	            let at = i - first[i];
 854	            match ctx.sub(&rows[i][at], s) {
 855	                Ok(d) => {
 856	                    rows[i][at] = d;
 857	                    shifted[i] = Some(d);
 858	                }
 859	                Err(e) => record(
 860	                    &mut refused[b],
 861	                    refusal_kind(e.into())?,
 862	                    BoundPass::ShiftFactor,
 863	                    i,
 864	                ),
 865	            }
 866	        }
 867	    }
 868	    let zero = Wide::<L>::ZERO;
 869	    let get = |rows: &Vec<Vec<Wide<L>>>, i: usize, j: usize| -> Wide<L> {
 870	        if j < first[i] {
 871	            zero
 872	        } else {
 873	            rows[i][j - first[i]]
 874	        }
 875	    };
 876	    let mut failed = vec![false; profile.blocks];
 877	    let mut work = vec![zero; n];
 878	    for i in 0..n {
 879	        let b = profile.block_of_row[i] as usize;
 880	        if refused[b].is_some() {
 881	            guard.check(ctx, sum)?;
 882	            continue;
 883	        }
 884	        // The row's operations; an exponent refusal ends the row (A2).
 885	        let mut row = || -> Result<Wide<L>, AttemptStop> {
 886	            for j in first[i]..i {
 887	                let mut s = get(&rows, i, j);
 888	                for kk in first[i].max(first[j])..j {
 889	                    let t = ctx.mul(&work[kk], &get(&rows, j, kk))?;
 890	                    s = ctx.sub(&s, &t)?;
 891	                }
 892	                work[j] = s;
 893	                let d = get(&rows, j, j);
 894	                rows[i][j - first[i]] = ctx.div(&s, &d)?;
 895	            }
 896	            let mut pivot = get(&rows, i, i);
 897	            for kk in first[i]..i {
 898	                let term = ctx.mul(&work[kk], &get(&rows, i, kk))?;
 899	                pivot = ctx.sub(&pivot, &term)?;
 900	            }
 901	            Ok(pivot)
 902	        };
 903	        let mut pivot = match row() {
 904	            Ok(p) => p,
 905	            Err(e) => {
 906	                record(&mut refused[b], refusal_kind(e)?, BoundPass::ShiftFactor, i);
 907	                Wide::<L>::ONE
 908	            }
 909	        };
 910	        if pivot.is_zero() || pivot.is_sign_negative() {
 911	            // The block has failed at this σ_c; its later rows are not used.
 912	            failed[b] = true;
 913	            pivot = Wide::<L>::ONE;
 914	        }
 915	        rows[i][i - first[i]] = pivot;
 916	        guard.check(ctx, sum)?;
 917	    }
 918	    Ok(ShiftedFactor {
 919	        first,
 920	        rows,
 921	        failed,
 922	        shifted,
 923	    })
 924	}
