 946	pub(crate) fn ceil_sqrt(n: usize) -> u64 {
 947	    let n = n as u64;
 948	    let mut r = (n as f64).sqrt() as u64;
 949	    while r * r > n {
 950	        r -= 1;
 951	    }
 952	    while r * r < n {
 953	        r += 1;
 954	    }
 955	    r
 956	}
