 970	/// Whether 7c's shift runs for a block with data: est_c > 0, and Uc_c missing
 971	/// or above 2·⌈√n_c⌉·est_c (exactly).
 972	pub(crate) fn shift_needed<const L: usize>(
 973	    sum: &mut ExactWideSum,
 974	    uc: &Option<Wide<L>>,
 975	    est: &Wide<L>,
 976	    n_c: usize,
 977	) -> Result<bool, AttemptStop>
 978	where
 979	    Wide<L>: SupportedWidth,
 980	{
 981	    // V-K seeded fault VK-R28 (R7-M28): no shift (Uc alone).
 982	    #[cfg(any(test, feature = "mutation-controls"))]
 983	    if super::seeded::active(super::seeded::Fault::R28) {
 984	        return Ok(false);
 985	    }
 986	    if est.is_zero() {
 987	        return Ok(false);
 988	    }
 989	    let Some(uc) = uc else {
 990	        return Ok(true);
 991	    };
 992	    sum.clear();
 993	    sum.add_wide(uc, false)?;
 994	    sum.add_wide_scaled(est, true, 2 * ceil_sqrt(n_c), 0)?;
 995	    let above = sum.signum() > 0;
 996	    sum.clear();
 997	    Ok(above)
 998	}
