1000	/// 7c's schedule for the blocks in `start` (block, σ_c, n_c): at most three
1001	/// shifted factorizations in all, each over the whole matrix with the blocks
1002	/// still failing shifted (their σ halved exactly after a failure). Returns each
1003	/// block's result and the number of factorizations.
1004	///
1005	/// RV23-1: when the schedule stops (a budget stop, say) after a refusal, each
1006	/// started block's refusal so far is recorded in `s_refused` before the stop
1007	/// propagates: those kept in the results of earlier factorizations, and those
1008	/// of the factorization in progress for the blocks it shifts. They are the
1009	/// refusals the results would have carried had it run on. On success
1010	/// `s_refused` is left to the caller, which records the results' refusals.
1011	pub(crate) fn shift_schedule<const L: usize>(
1012	    ctx: &mut WideContext<L>,
1013	    sum: &mut ExactWideSum,
1014	    guard: &StageGuard,
1015	    profile: &ScaledProfile<L>,
1016	    gamma: &Wide<L>,
1017	    start: &[(usize, Wide<L>, usize)],
1018	    s_refused: &mut [Option<BoundRefusal>],
1019	) -> Result<(Vec<(usize, ShiftResult<L>)>, u8), AttemptStop>
1020	where
1021	    Wide<L>: SupportedWidth,
1022	{
1023	    let mut results: Vec<(usize, ShiftResult<L>)> = start
1024	        .iter()
1025	        .map(|&(b, sigma, _)| {
1026	            (
1027	                b,
1028	                ShiftResult {
1029	                    sigma,
1030	                    tries: 0,
1031	                    n_l: None,
1032	                    delta: None,
1033	                    sigma_prime: None,
1034	                    s: None,
1035	                    refused: None,
1036	                },
1037	            )
1038	        })
1039	        .collect();
1040	    // RV23-1: the factorization in progress's shifted blocks and refusals,
1041	    // held here so that a stop after a refusal keeps it.
1042	    let mut in_flight: Vec<usize> = Vec::new();
1043	    let mut refused: Vec<Option<BoundRefusal>> = vec![None; profile.blocks];
1044	    // The factorizations (a closure, so the stop comes back here).
1045	    let mut steps = || -> Result<u8, AttemptStop> {
1046	        let mut current: Vec<(usize, Wide<L>, usize)> = start.to_vec();
1047	        let mut factorizations = 0u8;
1048	        while !current.is_empty() && factorizations < 3 {
1049	            let mut sigma = vec![None; profile.blocks];
1050	            for (b, s, _) in &current {
1051	                sigma[*b] = Some(*s);
1052	            }
1053	            in_flight.clear();
1054	            in_flight.extend(current.iter().map(|c| c.0));
1055	            refused.fill(None);
1056	            let f = shifted_factor(ctx, sum, guard, profile, &sigma, &mut refused)?;
1057	            factorizations += 1;
1058	            // A2: N′_L per block, a refusal of the factorization carried over.
1059	            let ct = nl_pass(ctx, sum, guard, &f, &profile.block_of_row, &mut refused)?;
1060	            let n_l = block_max(&ct, &profile.block_of_row, profile.blocks);
1061	            let mut next = Vec::new();
1062	            for (b, s, n_c) in current {
1063	                let r = &mut results
1064	                    .iter_mut()
1065	                    .find(|r| r.0 == b)
1066	                    .expect("a started block")
1067	                    .1;
1068	                r.tries += 1;
1069	                r.sigma = s;
1070	                if let Some(refusal) = refused[b] {
1071	                    // S_c is unavailable; a refusal is not retried (A2).
1072	                    r.refused = Some(refusal);
1073	                    continue;
1074	                }
1075	                if f.failed[b] {
1076	                    match s.mul_pow2(-1) {
1077	                        Ok(half) => next.push((b, half, n_c)),
1078	                        Err(e) => record(
1079	                            &mut r.refused,
1080	                            refusal_kind(e.into())?,
1081	                            BoundPass::ShiftForm,
1082	                            usize::MAX,
1083	                        ),
1084	                    }
1085	                    continue;
1086	                }
1087	                // δ_c = 2^(1−P)·max_{i∈c}|d̃_i|, exact.
1088	                let mut top = Wide::<L>::ZERO;
1089	                for (i, d) in f.shifted.iter().enumerate() {
1090	                    if profile.block_of_row[i] as usize == b {
1091	                        if let Some(d) = d {
1092	                            if d.abs().cmp_value(&top) == CmpOrdering::Greater {
1093	                                top = d.abs();
1094	                            }
1095	                        }
1096	                    }
1097	                }
1098	                let form = |ctx: &mut WideContext<L>,
1099	                            sum: &mut ExactWideSum|
1100	                 -> Result<(Wide<L>, Wide<L>, Option<Wide<L>>), AttemptStop> {
1101	                    let delta = top.mul_pow2(1 - i64::from(ctx.precision()))?;
1102	                    let gn = mul_toward(ctx, sum, gamma, &n_l[b], Toward::Up)?;
1103	                    let e = add_toward(ctx, sum, &gn, &delta, Toward::Up)?;
1104	                    let sp = sub_toward(ctx, sum, &s, &e, Toward::Down)?;
1105	                    let sv = if !sp.is_zero() && !sp.is_sign_negative() {
1106	                        let root = Wide::<L>::from_f64(ceil_sqrt(n_c) as f64)?;
1107	                        Some(div_toward(ctx, sum, &root, &sp, Toward::Up)?)
1108	                    } else {
1109	                        None
1110	                    };
1111	                    Ok((delta, sp, sv))
1112	                };
1113	                let formed = form(ctx, sum);
1114	                if let Some((delta, sp, sv)) = refusable(
1115	                    formed,
1116	                    sum,
1117	                    &mut r.refused,
1118	                    BoundPass::ShiftForm,
1119	                    usize::MAX,
1120	                )? {
1121	                    r.n_l = Some(n_l[b]);
1122	                    r.delta = Some(delta);
1123	                    r.sigma_prime = Some(sp);
1124	                    r.s = sv;
1125	                }
1126	            }
1127	            current = next;
1128	        }
1129	        Ok(factorizations)
1130	    };
1131	    let steps = steps();
1132	    if steps.is_err() {
1133	        for (b, r) in &results {
1134	            if let Some(x) = r.refused {
1135	                record(&mut s_refused[*b], x.kind, x.pass, x.row);
1136	            }
1137	        }
1138	        for &b in &in_flight {
1139	            if let Some(x) = refused[b] {
1140	                record(&mut s_refused[b], x.kind, x.pass, x.row);
1141	            }
1142	        }
1143	    }
1144	    let factorizations = steps?;
1145	    Ok((results, factorizations))
1146	}
