 419	/// Builds `VerifyShared` from the verification precision's shared stages.
 420	pub(crate) fn build_verify_shared<const L: usize, const R: usize, const W: usize>(
 421	    shared: &Shared<L, R>,
 422	    source: &PrimitiveSource,
 423	    group: &GroupPrep,
 424	    guard: StageGuard,
 425	) -> VerifySpent<VerifyShared<L, W>>
 426	where
 427	    Wide<L>: SupportedWidth,
 428	    Wide<R>: SupportedWidth,
 429	    Wide<W>: SupportedWidth,
 430	{
 431	    let p = shared.p;
 432	    let q_w = q_w_of(p);
 433	    let mut ctx = WideContext::<L>::new(p).expect("supported precision");
 434	    let mut ctx_w = WideContext::<W>::new(q_w).expect("supported precision");
 435	    let mut sum = ExactWideSum::new();
 436	    let mut stages = StageWork::default();
 437	    // T3 KF3: the stage in progress, for a stopped build's unstaged work.
 438	    let mut current = Stage::BoundedFormation;
 439	    // RV23-1: the Uc_c refusal slots, one per block, held outside the build so
 440	    // that a stop after a refusal keeps it in the evidence.
 441	    let mut uc_refused: Vec<Option<BoundRefusal>> = vec![None; group.blocks.len()];
 442	    let mut run = || -> Result<VerifyShared<L, W>, AttemptStop> {
 443	        let spent = |ctx: &WideContext<L>, ctx_w: &WideContext<W>, sum: &ExactWideSum| {
 444	            lme(ctx) + lme(ctx_w) + sum.work().limb_multiply_equivalents()
 445	        };
 446	        let t0 = spent(&ctx, &ctx_w, &sum);
 447	        let g = guard;
 448	        let bounded: Vec<BoundedCoefficients<L>> =
 449	            shared.members.iter().map(|m| m.bounded()).collect();
 450	        let abar = assemble_bounded(
 451	            &mut ctx,
 452	            &mut sum,
 453	            &g,
 454	            source,
 455	            &group.structure,
 456	            &bounded,
 457	            &shared.directional,
 458	        )?;
 459	        let t1 = spent(&ctx, &ctx_w, &sum);
 460	        stages.bounded_formation = t1 - t0;
 461	        current = Stage::WideFormation;
 462	        let (ke_w, directional_w) = if q_w == p {
 463	            (
 464	                shared
 465	                    .members
 466	                    .iter()
 467	                    .map(|m| full_ke(m).map(|row| row.map(|v| v.widen::<W>())))
 468	                    .collect(),
 469	                shared
 470	                    .directional
 471	                    .iter()
 472	                    .map(|d| d.k.map(|row| row.map(|v| v.widen::<W>())))
 473	                    .collect(),
 474	            )
 475	        } else {
 476	            let gw = guard.with_base(lme(&ctx));
 477	            let members_w = form_members(&mut ctx_w, &mut sum, &gw, source)?;
 478	            let directional_w = form_directional(&mut ctx_w, &mut sum, source)?;
 479	            (
 480	                members_w.iter().map(full_ke).collect(),
 481	                directional_w.iter().map(|d| d.k).collect(),
 482	            )
 483	        };
 484	        let t2 = spent(&ctx, &ctx_w, &sum);
 485	        stages.wide_formation = t2 - t1;
 486	        current = Stage::Uc;
 487	        let gu = guard.with_base(lme(&ctx_w));
 488	        let nf = group.ordering.free.len();
 489	        let gamma = gamma_m(&mut ctx, &mut sum, nf)?;
 490	        let rows = block_of_rows(&group.ordering, &group.blocks);
 491	        // Amendment A2: a refusal makes only its block's Uc_c unavailable; it
 492	        // no longer stops the build.
 493	        let uc = uc_bounds(
 494	            &mut ctx,
 495	            &mut sum,
 496	            &gu,
 497	            &shared.factor,
 498	            &rows,
 499	            &mut uc_refused,
 500	            &gamma,
 501	        )?;
 502	        let t3 = spent(&ctx, &ctx_w, &sum);
 503	        stages.uc = t3 - t2;
 504	        Ok(VerifyShared {
 505	            q_w,
 506	            abar,
 507	            ke_w,
 508	            directional_w,
 509	            gamma,
 510	            uc,
 511	            work: AttemptWork::default(),
 512	            sum_work: SumWork::default(),
 513	            stages: StageWork::default(),
 514	            total: 0,
 515	        })
 516	    };
 517	    let result = run();
 518	    let mut work = AttemptWork::default();
 519	    work.record(&ctx);
 520	    work.record(&ctx_w);
 521	    let sum_work = sum.work();
 522	    let total = work.limb_multiply_equivalents() + sum_work.limb_multiply_equivalents();
 523	    stages.close_stopped(&result, current, total);
 524	    // RV23-1: a stopped build's Uc_c refusals (a completed build's are in `uc`).
 525	    let refusals = if result.is_err() {
 526	        uc_refusals(&uc_refused)
 527	    } else {
 528	        Vec::new()
 529	    };
 530	    let result = result.map(|mut v| {
 531	        v.work = work;
 532	        v.sum_work = sum_work;
 533	        v.stages = stages.clone();
 534	        v.total = total;
 535	        v
 536	    });
 537	    VerifySpent {
 538	        result,
 539	        work,
 540	        sum_work,
 541	        stages,
 542	        total,
 543	        refusals,
 544	    }
 545	}
