291	/// The call's segments in the schedule's time order (module documentation).
292	pub fn segments(attempts: &[AttemptRecord]) -> Vec<Segment> {
293	    let mut out = Vec::new();
294	    let mut total = 0u64;
295	    for (i, a) in attempts.iter().enumerate() {
296	        let own_solve = own_total(a)
297	            .saturating_sub(a.verification_work)
298	            .saturating_sub(a.stop_rule_work);
299	        total = total
300	            .saturating_add(a.shared_work)
301	            .saturating_add(own_solve);
302	        out.push(Segment {
303	            label: format!("solve_{}", a.precision),
304	            end: total,
305	        });
306	        let verified =
307	            a.verification.is_some() || a.verification_work > 0 || a.verification_shared_work > 0;
308	        if verified {
309	            total = total
310	                .saturating_add(a.verification_shared_work)
311	                .saturating_add(a.verification_work);
312	            out.push(Segment {
313	                label: format!("verify_{}", a.precision),
314	                end: total,
315	            });
316	            if i > 0 && attempts[i - 1].stop_rule_work > 0 {
317	                total = total.saturating_add(attempts[i - 1].stop_rule_work);
318	                out.push(Segment {
319	                    label: format!("decide_{}", attempts[i - 1].precision),
320	                    end: total,
321	                });
322	            }
323	        }
324	    }
325	    out
326	}
