328	/// Parity `w1_prefix_segments` for prefix j (1-based): the prefix call ended on
329	/// the case budget, and its first j segments equal the full call's (RV22-N3:
330	/// the binary's predicate, here so that it is tested).
331	pub fn prefix_matches(j: usize, full: &[AttemptRecord], prefix: &CaseOutcome) -> bool {
332	    let full_segments = segments(full);
333	    let own = segments(attempts_of(prefix));
334	    let budget_stop = matches!(
335	        prefix,
336	        CaseOutcome::Unresolved {
337	            reason: UnresolvedReason::Budget(_),
338	            ..
339	        }
340	    );
341	    budget_stop && own.len() >= j && full_segments.len() > j && own[..j] == full_segments[..j]
342	}
343	
344	/// The prefix limits: every segment's end but the last (the last is the full
345	/// call).
346	pub fn prefix_limits(attempts: &[AttemptRecord]) -> Vec<(String, u64)> {
347	    let segs = segments(attempts);
348	    segs.iter()
349	        .take(segs.len().saturating_sub(1))
350	        .map(|s| (s.label.clone(), s.end))
351	        .collect()
352	}

