1243	fn build_shared<const L: usize, const R: usize>(
1244	    p: u32,
1245	    q: u32,
1246	    source: &PrimitiveSource,
1247	    group: &GroupPrep,
1248	    guard: StageGuard,
1249	) -> Spent<Shared<L, R>>
1250	where
1251	    Wide<L>: SupportedWidth,
1252	    Wide<R>: SupportedWidth,
1253	{
1254	    let mut ctx = WideContext::<L>::new(p).expect("supported precision");
1255	    let mut ctx_q = WideContext::<R>::new(q).expect("supported precision");
1256	    let mut ctx16 = WideContext::<16>::new(1024).expect("supported precision");
1257	    let mut ctx64 = WideContext::<4>::new(64).expect("supported precision");
1258	    let mut sum = ExactWideSum::new();
1259	    let mut stages = StageWork::default();
1260	    // T3 KF3: the stage in progress, for a stopped build's unstaged work.
1261	    let mut current = Stage::Formation;
1262	    let mut run = || -> Result<Shared<L, R>, AttemptStop> {
1263	        let t0 = lme(&ctx) + sum.work().limb_multiply_equivalents();
1264	        let g = guard.with_base(0);
1265	        let members = form_members(&mut ctx, &mut sum, &g, source)?;
1266	        let directional = form_directional(&mut ctx, &mut sum, source)?;
1267	        let t1 = lme(&ctx) + sum.work().limb_multiply_equivalents();
1268	        stages.formation = t1 - t0;
1269	        current = Stage::Assembly;
1270	        let k = assemble(
1271	            &mut ctx,
1272	            &mut sum,
1273	            &g,
1274	            source,
1275	            &group.structure,
1276	            &members,
1277	            &directional,
1278	        )?;
1279	        let t2 = lme(&ctx) + sum.work().limb_multiply_equivalents();
1280	        stages.assembly = t2 - t1;
1281	        g.check(&ctx, &sum)?;
1282	        current = Stage::ResidualFormation;
1283	        // The residual system re-formed at q (the ceiling: K itself, widened),
1284	        // with the coefficients the gate's fallback forms Ā^q from.
1285	        type AtQ<const R: usize> = (
1286	            Vec<Wide<R>>,
1287	            Vec<BoundedCoefficients<R>>,
1288	            Vec<DirectionalBlock<R>>,
1289	        );
1290	        let (k_q, bounded_q, directional_q): AtQ<R> = if q == p {
1291	            (
1292	                k.iter().map(|w| w.widen::<R>()).collect(),
1293	                members.iter().map(|m| m.bounded().widen::<R>()).collect(),
1294	                directional.iter().map(|d| d.widen::<R>()).collect(),
1295	            )
1296	        } else {
1297	            let gq = guard.with_base(lme(&ctx));
1298	            let members_q = form_members(&mut ctx_q, &mut sum, &gq, source)?;
1299	            let directional_q = form_directional(&mut ctx_q, &mut sum, source)?;
1300	            let k_q = assemble(
1301	                &mut ctx_q,
1302	                &mut sum,
1303	                &gq,
1304	                source,
1305	                &group.structure,
1306	                &members_q,
1307	                &directional_q,
1308	            )?;
1309	            (
1310	                k_q,
1311	                members_q.iter().map(|m| m.bounded()).collect(),
1312	                directional_q,
1313	            )
1314	        };
1315	        let t3 = lme(&ctx) + lme(&ctx_q) + sum.work().limb_multiply_equivalents();
1316	        stages.residual_formation = t3 - t2;
1317	        current = Stage::Factor;
1318	        let gp = guard.with_base(lme(&ctx_q));
1319	        let factor = super::factor::factor(
1320	            &mut ctx,
1321	            &mut sum,
1322	            &gp,
1323	            &group.structure,
1324	            &k,
1325	            &group.ordering,
1326	        )?;
1327	        let t4 = lme(&ctx) + lme(&ctx_q) + sum.work().limb_multiply_equivalents();
1328	        stages.factor = t4 - t3;
1329	        current = Stage::Condition;
1330	        // At p ≥ 256 the screen's solves also give est_c per block (read only).
1331	        let (rcond, est_blocks) = if p >= 256 {
1332	            let mut ratios = BlockRatios::new(&group.blocks);
1333	            let rcond = factor.condition_observed(
1334	                &mut ctx,
1335	                &mut sum,
1336	                &group.structure,
1337	                &k,
1338	                &group.ordering,
1339	                Some(&mut ratios),
1340	            )?;
1341	            (rcond, ratios.estimates())
1342	        } else {
1343	            let rcond =
1344	                factor.condition(&mut ctx, &mut sum, &group.structure, &k, &group.ordering)?;
1345	            (rcond, Vec::new())
1346	        };
1347	        gp.check(&ctx, &sum)?;
1348	        let rcond_value = publish_value(&rcond).value().unwrap_or(0.0);
1349	        // The pivot margin minimum, rounded downward.
1350	        let mut tracker = BoundedExtremeTracker::new(Direction::Down);
1351	        for screen in &factor.screens {
1352	            let mut num = ExactWideSum::new();
1353	            num.add_wide_scaled(&screen.pivot, false, 1, i64::from(p))?;
1354	            num.add_wide_scaled(&screen.pivot, true, screen.operations, 0)?;
1355	            let mut den = ExactWideSum::new();
1356	            den.add_wide_scaled(&screen.scale, false, 64 * screen.operations, 0)?;
1357	            if den.is_zero() {
1358	                continue;
1359	            }
1360	            tracker.offer(&mut ctx64, &mut ctx16, num, den)?;
1361	        }
1362	        let margin = tracker.finish(&mut ctx16)?.unwrap_or(f64::INFINITY);
1363	        let t5 = lme(&ctx)
1364	            + lme(&ctx_q)
1365	            + sum.work().limb_multiply_equivalents()
1366	            + lme(&ctx16)
1367	            + lme(&ctx64);
1368	        stages.condition = t5 - t4;
1369	        Ok(Shared {
1370	            p,
1371	            q,
1372	            members,
1373	            directional,
1374	            k,
1375	            k_q,
1376	            bounded_q,
1377	            directional_q,
1378	            factor,
1379	            est_blocks,
1380	            rcond: rcond_value,
1381	            pivot_margin_min: margin,
1382	            work: AttemptWork::default(),
1383	            sum_work: SumWork::default(),
1384	            stages: StageWork::default(),
1385	            total: 0,
1386	        })
1387	    };
1388	    let result = run();
1389	    let mut work = AttemptWork::default();
1390	    work.record(&ctx);
