3013	/// D1 revision 5a.3's verification pass on a solved verification state: the
3014	/// shared verification data (built or reused) and the case's own pass, both
3015	/// charged to the verification attempt, the case budget and the meter (the
3016	/// shared data once against the invocation).
3017	fn verify_precision(
3018	    state: &PrecisionState,
3019	    prep: &Arc<CasePrep>,
3020	    group: &Arc<GroupPrep>,
3021	    cache: &mut GroupCache,
3022	    budget: &mut CaseBudget,
3023	    meter: &mut InvocationMeter,
3024	    record: &mut AttemptRecord,
3025	) -> Result<VerificationState, AttemptStop> {
3026	    let case_room = budget.limit.saturating_sub(budget.used);
3027	    let invocation_room = meter.room();
3028	    let guard = StageGuard {
3029	        base: 0,
3030	        case_room,
3031	        invocation_room,
3032	    };
3033	    macro_rules! run {
3034	        ($slot:expr, $vslot:expr, $L:literal, $R:literal, $W:literal, $solved:expr, $variant:ident) => {{
3035	            let shared = match $slot {
3036	                Some(Ok(shared)) => shared.clone(),
3037	                _ => unreachable!("a solved state's shared stages are cached"),
3038	            };
3039	            let (vs, vs_total, built, vs_stages, vs_refusals) =
3040	                obtain_verify::<$L, $R, $W>($vslot, &shared, &prep.source, group, guard);
3041	            record.verification_shared_work = vs_total;
3042	            record.verification_shared_built_here = built;
3043	            record.shared_stages.add(&vs_stages);
