505	pub(crate) fn factor<const L: usize>(
506	    ctx: &mut WideContext<L>,
507	    sum: &mut ExactWideSum,
508	    guard: &StageGuard,
509	    structure: &Structure,
510	    k: &[Wide<L>],
511	    ordering: &Ordering,
512	) -> Result<RetainedFactor<L>, AttemptStop>
513	where
514	    Wide<L>: SupportedWidth,
515	{
516	    let p = ctx.precision();
517	    let n = ordering.free.len();
518	    let zero = Wide::<L>::ZERO;
519	    // Radix equilibration.
520	    let mut scale = Vec::with_capacity(n);
521	    for &g in &ordering.free {
522	        let d = stored(structure, k, g, g).unwrap_or(zero);
523	        if d.is_zero() {
524	            return Err(AttemptStop::ZeroDiagonal { global_dof: g });
525	        }
526	        if d.is_sign_negative() {
527	            return Err(AttemptStop::NegativeEnergy { i: g, j: g });
528	        }
529	        scale.push(-d.exponent().div_euclid(2));
530	    }
531	    // Scaled ordered rows.
532	    let mut rows: Vec<Vec<Wide<L>>> = Vec::with_capacity(n);
533	    for i in 0..n {
534	        let a = ordering.order[i];
535	        let g = ordering.free[a];
536	        let f = ordering.first[i];
537	        let mut row = vec![zero; i - f + 1];
538	        for index in structure.pattern.row_range(g) {
539	            let c = structure.pattern.column(index);
540	            let b = ordering.position[c];
541	            if b == usize::MAX {
542	                continue;
543	            }
544	            let j = ordering.rank[b];
545	            if j <= i {
546	                debug_assert!(j >= f);
547	                row[j - f] = k[index].mul_pow2(scale[a] + scale[b])?;
548	            }
549	        }
550	        rows.push(row);
551	    }
552	    let first = ordering.first.clone();
553	    let get = |rows: &Vec<Vec<Wide<L>>>, i: usize, j: usize| -> Wide<L> {
554	        if j < first[i] {
555	            zero
556	        } else {
557	            rows[i][j - first[i]]
558	        }
559	    };
560	    let mut work = vec![zero; n];
561	    let mut screens = Vec::with_capacity(n);
562	    for i in 0..n {
563	        for j in first[i]..i {
564	            let mut s = get(&rows, i, j);
565	            for kk in first[i].max(first[j])..j {
566	                let t = ctx.mul(&work[kk], &get(&rows, j, kk))?;
567	                s = ctx.sub(&s, &t)?;
568	            }
569	            work[j] = s;
570	            let d = get(&rows, j, j);
571	            rows[i][j - first[i]] = ctx.div(&s, &d)?;
572	        }
573	        let mut pivot = get(&rows, i, i);
574	        let mut cancellation = pivot.abs();
575	        for kk in first[i]..i {
576	            let term = ctx.mul(&work[kk], &get(&rows, i, kk))?;
577	            pivot = ctx.sub(&pivot, &term)?;
578	            cancellation = ctx.add(&cancellation, &term.abs())?;
579	        }
580	        let operations = 2 * (i - first[i]) as u64 + 2;
581	        if !pivot_passes(sum, &pivot, &cancellation, operations, p)? {
582	            let global = ordering.free[ordering.order[i]];
583	            return Err(match negative_pair(sum, structure, k, ordering, p)? {
584	                Some((a, b)) => AttemptStop::NegativeEnergy { i: a, j: b },
585	                None => AttemptStop::Pivot { global_dof: global },
586	            });
587	        }
588	        screens.push(PivotScreen {
589	            pivot,
590	            scale: cancellation,
591	            operations,
592	        });
593	        rows[i][i - first[i]] = pivot;
594	        guard.check(ctx, sum)?;
595	    }
596	    Ok(RetainedFactor {
597	        order: ordering.order.clone(),
598	        first,
599	        rows,
600	        scale,
601	        screens,
602	    })
603	}
