605	impl<const L: usize> RetainedFactor<L>
606	where
607	    Wide<L>: SupportedWidth,
608	{
609	    /// L's (i, j) entry for j < i, D's for j = i, in elimination order (read
610	    /// by the certified bounds, R7 §4.1.6.3 item 7b).
611	    pub(crate) fn get(&self, i: usize, j: usize) -> Wide<L> {
612	        if j < self.first[i] {
613	            Wide::<L>::ZERO
614	        } else {
615	            self.rows[i][j - self.first[i]]
616	        }
617	    }
618	
619	    /// First stored column of each ordered row.
620	    pub(crate) fn first(&self) -> &[usize] {
621	        &self.first
622	    }
623	
624	    /// The radix scale exponent of each free position (s_a = 2^scale[a]).
625	    pub(crate) fn scale(&self) -> &[i64] {
626	        &self.scale
627	    }
628	
629	    /// K̃ x = b, both in free-position order (ProfileFactor::solve's loops).
630	    pub(crate) fn solve_scaled(
631	        &self,
632	        ctx: &mut WideContext<L>,
633	        rhs: &[Wide<L>],
634	    ) -> Result<Vec<Wide<L>>, AttemptStop> {
635	        let n = self.order.len();
636	        let mut x: Vec<Wide<L>> = self.order.iter().map(|&a| rhs[a]).collect();
637	        for i in 0..n {
638	            for j in self.first[i]..i {
639	                let t = ctx.mul(&self.get(i, j), &x[j])?;
640	                x[i] = ctx.sub(&x[i], &t)?;
641	            }
642	        }
643	        for (i, value) in x.iter_mut().enumerate() {
644	            *value = ctx.div(value, &self.get(i, i))?;
645	        }
646	        for i in (0..n).rev() {
647	            let v = x[i];
648	            for j in self.first[i]..i {
649	                let t = ctx.mul(&self.get(i, j), &v)?;
650	                x[j] = ctx.sub(&x[j], &t)?;
651	            }
652	        }
653	        let mut out = vec![Wide::<L>::ZERO; n];
654	        for (i, &a) in self.order.iter().enumerate() {
655	            out[a] = x[i];
656	        }
657	        Ok(out)
658	    }
659	
660	    /// K x = b in free-position order: b scaled by S, solved, x = S y (exact
661	    /// scalings).
662	    pub(crate) fn solve(
663	        &self,
664	        ctx: &mut WideContext<L>,
665	        rhs: &[Wide<L>],
666	    ) -> Result<Vec<Wide<L>>, AttemptStop> {
667	        let scaled: Vec<Wide<L>> = rhs
668	            .iter()
669	            .zip(&self.scale)
670	            .map(|(b, &s)| b.mul_pow2(s))
671	            .collect::<Result<_, _>>()?;
672	        let y = self.solve_scaled(ctx, &scaled)?;
673	        Ok(y.iter()
674	            .zip(&self.scale)
675	            .map(|(v, &s)| v.mul_pow2(s))
676	            .collect::<Result<_, _>>()?)
677	    }
