 625	/// at least as early dominates. The window removes rows by key alone, and a
 626	/// dominating entry's key is nearer the best, so it outlasts every row it
 627	/// dominates: the result is the same for any collapse schedule (KF1 plan §2).
 628	pub(crate) struct BoundedExtremeTracker {
 629	    direction: Direction,
 630	    limit: usize,
 631	    best: Option<u64>,
 632	    offered: u64,
 633	    /// Unevaluated rows: (num, den, key, place in the stream).
 634	    lazy: Vec<(ExactWideSum, ExactWideSum, u64, u64)>,
 635	    /// Evaluated entries (key, outcome), nearest the best first.
 636	    table: Vec<(u64, Evaluated)>,
 637	}
 638	
 639	impl BoundedExtremeTracker {
 640	    pub(crate) fn new(direction: Direction) -> Self {
 641	        Self::with_limit(direction, tracker_rows())
 642	    }
 643	
 644	    pub(crate) fn with_limit(direction: Direction, limit: usize) -> Self {
 645	        Self {
 646	            direction,
 647	            limit: limit.max(1),
 648	            best: None,
 649	            offered: 0,
 650	            lazy: Vec::new(),
 651	            table: Vec::new(),
 652	        }
 653	    }
 654	
 655	    pub(crate) fn offer(
 656	        &mut self,
 657	        ctx64: &mut WideContext<4>,
 658	        ctx16: &mut WideContext<16>,
 659	        num: ExactWideSum,
 660	        den: ExactWideSum,
 661	    ) -> Result<(), AttemptStop> {
 662	        let key = approximate_ratio(ctx64, &num, &den)?.to_bits();
 663	        let seq = self.offered;
 664	        self.offered += 1;
 665	        let better = match (self.best, self.direction) {
 666	            (None, _) => true,
 667	            (Some(b), Direction::Up) => key > b,
 668	            (Some(b), Direction::Down) => key < b,
 669	        };
 670	        if better {
 671	            self.best = Some(key);
 672	            self.lazy.retain(|row| in_window(row.2, key));
 673	            if self.lazy.is_empty() {
 674	                self.lazy = Vec::new();
 675	            }
 676	            self.table.retain(|entry| in_window(entry.0, key));
 677	        }
 678	        if self.best.is_some_and(|b| in_window(key, b)) {
 679	            if self.lazy.len() >= self.limit {
 680	                self.collapse(ctx16);
 681	            }
 682	            self.lazy.push((num, den, key, seq));
 683	        }
 684	        Ok(())
 685	    }
 686	
 687	    /// Evaluates the unevaluated rows exactly (a refusal is recorded, not
 688	    /// returned) and releases their memory.
 689	    pub(crate) fn collapse(&mut self, ctx16: &mut WideContext<16>) {
 690	        let lazy = std::mem::take(&mut self.lazy);
 691	        if lazy.is_empty() {
 692	            return;
 693	        }
 694	        for (num, den, key, seq) in &lazy {
 695	            let outcome = match directed_ratio(ctx16, num, den, self.direction) {
 696	                Ok(value) => Evaluated::Ratio(value),
 697	                Err(stop) => Evaluated::Refused { seq: *seq, stop },
 698	            };
 699	            self.table.push((*key, outcome));
 700	        }
 701	        drop(lazy);
 702	        self.prune();
 703	    }
 704	
 705	    /// Keeps the entries no other entry dominates: sorted nearest the best
 706	    /// first (within a key, the most decisive first), an entry stays only if it
 707	    /// decides `finish` ahead of every entry kept before it.
 708	    fn prune(&mut self) {
 709	        let direction = self.direction;
 710	        self.table.sort_by(|a, b| {
 711	            let by_key = match direction {
 712	                Direction::Up => b.0.cmp(&a.0),
 713	                Direction::Down => a.0.cmp(&b.0),
 714	            };
 715	            by_key.then_with(|| {
 716	                if a.1.beats(&b.1, direction) {
 717	                    CmpOrdering::Less
 718	                } else if b.1.beats(&a.1, direction) {
 719	                    CmpOrdering::Greater
 720	                } else {
 721	                    CmpOrdering::Equal
 722	                }
 723	            })
 724	        });
 725	        let mut kept: Vec<(u64, Evaluated)> = Vec::new();
 726	        for entry in self.table.drain(..) {
 727	            if kept
 728	                .last()
 729	                .is_none_or(|last| entry.1.beats(&last.1, direction))
 730	            {
 731	                kept.push(entry);
 732	            }
 733	        }
 734	        kept.shrink_to_fit();
 735	        self.table = kept;
 736	    }
