 738	    pub(crate) fn finish(self, ctx16: &mut WideContext<16>) -> Result<Option<f64>, AttemptStop> {
 739	        let mut best: Option<f64> = None;
 740	        let mut refused: Option<(u64, AttemptStop)> = None;
 741	        for (_, outcome) in self.table {
 742	            match outcome {
 743	                Evaluated::Ratio(value) => best = Some(extreme(best, value, self.direction)),
 744	                Evaluated::Refused { seq, stop } => {
 745	                    if refused.as_ref().is_none_or(|r| seq < r.0) {
 746	                        refused = Some((seq, stop));
 747	                    }
 748	                }
 749	            }
 750	        }
 751	        // A refusal among the evaluated rows came before every unevaluated row.
 752	        if let Some((_, stop)) = refused {
 753	            return Err(stop);
 754	        }
 755	        for (num, den, _, _) in &self.lazy {
 756	            let exact = directed_ratio(ctx16, num, den, self.direction)?;
 757	            best = Some(extreme(best, exact, self.direction));
 758	        }
 759	        Ok(best)
 760	    }
