 798	    pub(crate) fn offer(
 799	        &mut self,
 800	        key: K,
 801	        direction: Direction,
 802	        ctx64: &mut WideContext<4>,
 803	        ctx16: &mut WideContext<16>,
 804	        num: ExactWideSum,
 805	        den: ExactWideSum,
 806	    ) -> Result<(), AttemptStop> {
 807	        let tracker = self
 808	            .trackers
 809	            .entry(key)
 810	            .or_insert_with(|| BoundedExtremeTracker::new(direction));
 811	        let before = tracker.capacity();
 812	        tracker.offer(ctx64, ctx16, num, den)?;
 813	        let after = tracker.capacity();
 814	        self.held = self.held - before + after;
 815	        if before == 0 && after > 0 {
 816	            self.holding.insert(key);
 817	        } else if before > 0 && after == 0 {
 818	            self.holding.remove(&key);
 819	        }
 820	        if self.held > self.limit {
 821	            for k in std::mem::take(&mut self.holding) {
 822	                if let Some(t) = self.trackers.get_mut(&k) {
 823	                    t.collapse(ctx16);
 824	                }
 825	            }
 826	            self.held = 0;
 827	        }
 828	        Ok(())
 829	    }
