3119	    let mut states: Vec<PrecisionState> = Vec::new();
3120	    // A solved verification that becomes the next candidate.
3121	    let mut pending: Option<(PrecisionState, usize)> = None;
3122	    let mut c = 0;
3123	    while c < 3 {
3124	        let p = PRECISIONS[c];
3125	        let (candidate, candidate_index) = match pending.take() {
3126	            Some(state) => state,
3127	            None => {
3128	                let (result, record) = solve_precision(p, &prep, &group, cache, &mut budget, meter);
3129	                attempts.push(record);
3130	                let index = attempts.len() - 1;
3131	                match result {
3132	                    Ok(state) => {
3133	                        states.push(state.clone());
3134	                        (state, index)
3135	                    }
3136	                    Err(stop) => {
