3144	                    }
3145	                }
3146	            }
3147	        };
3148	        let verification_p = PRECISIONS[c + 1];
3149	        let (result, mut record) =
3150	            solve_precision(verification_p, &prep, &group, cache, &mut budget, meter);
3151	        record.role = AttemptRole::Verification;
3152	        attempts.push(record);
3153	        let v_index = attempts.len() - 1;
3154	        let verification = match result {
3155	            Ok(state) => {
3156	                states.push(state.clone());
3157	                state
3158	            }
3159	            Err(stop) => {
3160	                attempts[candidate_index].outcome =
3161	                    AttemptOutcome::Rejected(AttemptReason::VerificationFailed);
3162	                attempts[v_index].outcome =
3163	                    AttemptOutcome::Failed(AttemptReason::Stop(stop.clone()));
3164	                if stop.escalates() {
3165	                    // The failed verification cannot be the next candidate.
3166	                    c += 2;
3167	                    continue;
3168	                }
3169	                return finish_terminal(&stop, attempts, geometry);
3170	            }
3171	        };
3172	        // D1 revision 5a.3: the verification pass (charged to the verification).
3173	        let report = match verify_precision(
3174	            &verification,
3175	            &prep,
3176	            &group,
3177	            cache,
3178	            &mut budget,
3179	            meter,
3180	            &mut attempts[v_index],
3181	        ) {
3182	            Ok(report) => report,
3183	            Err(stop) => {
3184	                attempts[candidate_index].outcome =
3185	                    AttemptOutcome::Rejected(AttemptReason::VerificationFailed);
3186	                attempts[v_index].outcome =
3187	                    AttemptOutcome::Failed(AttemptReason::Stop(stop.clone()));
3188	                return finish_terminal(&stop, attempts, geometry);
3189	            }
3190	        };
3191	        let guard = StageGuard {
3192	            base: 0,
3193	            case_room: budget.limit.saturating_sub(budget.used),
3194	            invocation_room: meter.room(),
3195	        };
3196	        let decision = compare_states(
3197	            &prep.layout,
3198	            &prep.extents,
3199	            &candidate,
3200	            &verification,
3201	            &report,
3202	            guard,
3203	        );
3204	        // V-K seeded fault VK-F06 (§7.3-6): the candidate accepted whatever the
3205	        // verification's verdict (accepted on the pivot screen alone).
3206	        #[cfg(any(test, feature = "mutation-controls"))]
3207	        let decision = if super::seeded::active(super::seeded::Fault::F06)
3208	            && matches!(decision.result, Ok(false))
3209	        {
3210	            StopDecision {
3211	                result: Ok(true),
3212	                ..decision
3213	            }
3214	        } else {
3215	            decision
3216	        };
3217	        {
3218	            let record = &mut attempts[candidate_index];
3219	            record.stop_rule_work += decision.total;
3220	            record.stages.stop_rule += decision.total;
3221	            record.work.merge(&decision.work);
3222	            record.k4_work.merge(&decision.sum_work);
3223	        }
3224	        budget.used = budget.used.saturating_add(decision.total);
3225	        meter.charge(decision.total);
3226	        match decision.result {
3227	            Err(stop) => {
3228	                attempts[candidate_index].outcome =
3229	                    AttemptOutcome::Failed(AttemptReason::Stop(stop.clone()));
3230	                return finish_terminal(&stop, attempts, geometry);
3231	            }
3232	            Ok(true) => {
