3250	                    decision.rejection,
3251	                    &prep.layout,
3252	                    &group,
3253	                ));
3254	                // V-K seeded fault VK-F05 (§7.3-5): no escalation after a
3255	                // rejected candidate.
3256	                #[cfg(any(test, feature = "mutation-controls"))]
