3262	                    };
3263	                }
3264	                if c + 1 < 3 {
3265	                    attempts[v_index].role = AttemptRole::VerificationThenCandidate;
3266	                    pending = Some((verification, v_index));
3267	                }
3268	                c += 1;
3269	            }
3270	        }
3271	    }
3272	    CaseOutcome::Unresolved {
3273	        reason: UnresolvedReason::Ceiling,
3274	        attempts,
3275	        geometry,
3276	    }
3277	}
